func Count(n int) iter.Seq[int] {
	return func(yield func(int) bool) {
		for i := range n {
			fmt.Print("y", i, " ")
			if !yield(i) {
				fmt.Print("stop ")
				return
			}
		}
		fmt.Print("done ")
	}
}

func main() {
	for v := range Count(5) {
		if v == 2 {
			break
		}
		fmt.Print("v", v, " ")
	}
	fmt.Println()
}

